#include "wled.h"
#include "sync_proto.h"

/*
 * WLED sync protocol v2 (prototype) - see docs/udp-sync-v2.md
 */

// AI: below section was generated by an AI
/*
 * Model: soft-state replication with last-writer-wins.
 * - Every state change gets a version (seq, origin): seq is a Lamport clock (max of all seq seen + 1), origin the node id
 *   of the node where the change was made. Versions are totally ordered (seq first, origin breaks ties).
 * - Receivers apply a STATE only if its version is newer than the last one applied for that sync group, so duplicates,
 *   retries and heartbeats are idempotent and late/reordered datagrams never overwrite newer state.
 * - The origin of the latest change re-sends it periodically (heartbeat), so nodes that missed a change or joined late
 *   converge. A joining node also asks for the state (STATE_REQ). Nodes that applied a state do not re-advertise their
 *   own copy (it may differ from the original due to receive filters or strip length, and equal versions are never
 *   re-applied); instead they keep the origin's datagrams and relay them unchanged in answer to a STATE_REQ, so a node
 *   can join even when the origin is gone. Relays are suppressed once any node has answered.
 * - A node that rebooted (and lost its clock) catches up from heartbeats; if its first change is still older than what
 *   others have applied, they answer with a CLOCK message and the node re-sends its change with a newer version.
 * Ideas borrowed from JGroups (identity, sequence numbers, state transfer on join, heartbeats), without reliable delivery:
 * only convergence to the latest state matters, intermediate states need not be delivered.
 */

#ifndef WLED_SYNC_V2_HEARTBEAT
  #define WLED_SYNC_V2_HEARTBEAT 15000  // ms between heartbeats
#endif
#define SYNC_V2_HEARTBEAT_JITTER  1000  // ms random extra delay, so nodes do not heartbeat in lock-step
#define SYNC_V2_JOIN_DELAY        1000  // ms after connecting before asking for the state
#define SYNC_V2_CLOCK_WINDOW      2000  // ms after a local change in which a CLOCK reply makes us re-send it with a newer version
#define SYNC_V2_CLOCK_MIN_GAP      500  // ms between CLOCK replies
#define SYNC_V2_NETWORK_DELAY        3  // presumed network delay (ms), added to transmitted times
#define SYNC_V2_KEEP_OPTIONS    0x0031  // Segment::options bits never synced: selected, freeze, reset
#define SYNC_V2_NUM_GROUPS           8

static constexpr size_t SYNC_V2_PART_BASE = sizeof(SyncV2Header) + sizeof(SyncV2Tlv) + sizeof(SyncV2Global);
static constexpr size_t SYNC_V2_NODEINFO_SIZE = sizeof(SyncV2Tlv) + sizeof(SyncV2NodeInfo);
static constexpr size_t SYNC_V2_SEG_SIZE = sizeof(SyncV2Tlv) + sizeof(SyncV2Segment);
// largest datagram we can ever build: one part holding all segments (capped to the UDP maximum)
static constexpr size_t SYNC_V2_BUF_SIZE = std::min<size_t>(SYNC_V2_MAX_UDP,
  SYNC_V2_PART_BASE + SYNC_V2_NODEINFO_SIZE + WS2812FX::getMaxSegments() * SYNC_V2_SEG_SIZE);
static_assert(WS2812FX::getMaxSegments() <= 64, "SyncV2Global::segMask holds at most 64 segments");

// maximum number of parts a state is split into (ESP-NOW, all segments active)
static constexpr size_t SYNC_V2_MAX_PARTS = (WS2812FX::getMaxSegments() + (SYNC_V2_MAX_ESPNOW - SYNC_V2_PART_BASE) / SYNC_V2_SEG_SIZE - 1)
                                            / ((SYNC_V2_MAX_ESPNOW - SYNC_V2_PART_BASE) / SYNC_V2_SEG_SIZE);
static_assert(SYNC_V2_MAX_PARTS <= 16, "SyncV2Version::parts holds at most 16 parts");

struct SyncV2Version {
  uint32_t seq    = 0;
  uint32_t origin = 0;
  uint16_t parts  = 0;    // bit mask of parts applied
};

static uint32_t      nodeId = 0;           // our id, derived from the MAC address
static uint32_t      lamport = 0;          // highest seq seen or created
static SyncV2Version myVersion;            // version of our current state (what heartbeats advertise)
static bool          hasVersion = false;   // false: our state is not a versioned state (boot state, or changed without sending)
static SyncV2Version applied[SYNC_V2_NUM_GROUPS]; // last version applied per receive group
static unsigned long nextHeartbeat = 0;
static unsigned long lastChange = 0;       // time of last local change we originated
static bool          clockCorrected = true; // last local change was already re-sent after a CLOCK reply
static unsigned long lastClockSent = 0;

// original datagrams of the latest state received from another node, relayed unchanged to joining nodes; only the
// header's sender and flags are patched, so the content always matches the version (unlike a re-encoded local copy)
struct SyncV2Cache {
  uint32_t seq    = 0;
  uint32_t origin = 0;
  uint8_t  groups = 0;            // sync groups of the cached state
  uint8_t  parts  = 0;            // number of parts, 0: cache empty
  bool     espNow = false;        // received via ESP-NOW (part numbering depends on the transport)
  uint8_t *part[SYNC_V2_MAX_PARTS] = {};
  uint16_t len[SYNC_V2_MAX_PARTS]  = {};
};
static SyncV2Cache   cache;
static bool          relayPending = false; // a STATE_REQ is to be answered from the cache
static unsigned long relayAt = 0;
static byte          lastCallMode = CALL_MODE_INIT;

static uint32_t getNodeId() {
  if (!nodeId) {
    // lower 32 bits of the MAC address (escapedMac is 12 lowercase hex chars)
    size_t l = escapedMac.length();
    nodeId = strtoul(escapedMac.c_str() + (l > 8 ? l - 8 : 0), nullptr, 16);
    if (!nodeId) nodeId = 1; // 0 is reserved for "no origin"
  }
  return nodeId;
}

// >0 if version a is newer than b, <0 if older, 0 if equal; seq comparison is wrap-around safe
static int compareVersion(uint32_t aSeq, uint32_t aOrigin, uint32_t bSeq, uint32_t bOrigin) {
  if (aSeq != bSeq) return int32_t(aSeq - bSeq) > 0 ? 1 : -1;
  if (aOrigin != bOrigin) return aOrigin > bOrigin ? 1 : -1;
  return 0;
}

static inline uint16_t partBit(uint8_t part) { return 1 << std::min<uint8_t>(part, 15); }

static inline bool espNowSyncActive() {
#ifndef WLED_DISABLE_ESPNOW
  return enableESPNow && useESPNowSync && statusESPNow == ESP_NOW_STATE_ON;
#else
  return false;
#endif
}

/*
 * transport
 */
static void sendUdp(const uint8_t *buf, size_t len) {
  if (!udpConnected) return;
  IPAddress broadcastIp = ~uint32_t(WLEDNetwork.subnetMask()) | uint32_t(WLEDNetwork.gatewayIP());
  notifierUdp.beginPacket(broadcastIp, udpPort);
  notifierUdp.write(buf, len);
  notifierUdp.endPacket();
}

static void sendEspNow(const uint8_t *buf, size_t len) {
#ifndef WLED_DISABLE_ESPNOW
  if (!espNowSyncActive()) return;
  if (wled::espNow.send(ESPNOW_BROADCAST_ADDRESS, buf, len)) DEBUG_PRINTLN(F("Sync v2: ESP-NOW send failed."));
#endif
}

static void fillHeader(SyncV2Header &h, uint8_t msgType, uint8_t flags, uint8_t groups) {
  h.magic[0] = SYNC_V2_MAGIC0; h.magic[1] = SYNC_V2_MAGIC1; h.magic[2] = SYNC_V2_MAGIC2; h.magic[3] = SYNC_V2_MAGIC3;
  h.version    = SYNC_V2_VERSION;
  h.msgType    = msgType;
  h.flags      = flags;
  h.groups     = groups;
  h.sender     = getNodeId();
  h.origin     = myVersion.origin;
  h.seq        = myVersion.seq;
  h.part       = 0;
  h.parts      = 1;
  h.payloadLen = 0;
}

// header-only message (STATE_REQ, CLOCK) on all transports
static void sendControl(uint8_t msgType, uint8_t groups) {
  SyncV2Header h;
  fillHeader(h, msgType, 0, groups);
  h.origin = getNodeId();
  h.seq    = lamport;
  sendUdp(reinterpret_cast<const uint8_t*>(&h), sizeof(h));
  sendEspNow(reinterpret_cast<const uint8_t*>(&h), sizeof(h));
}

/*
 * building STATE messages
 */
static void appendTlv(uint8_t *buf, size_t &len, uint8_t type, const void *data, size_t dataLen) {
  SyncV2Tlv t = { type, uint8_t(dataLen) };
  memcpy(buf + len, &t, sizeof(t));
  memcpy(buf + len + sizeof(t), data, dataLen);
  len += sizeof(t) + dataLen;
}

static void fillGlobal(SyncV2Global &g) {
  memset(&g, 0, sizeof(g));
  g.bri                 = bri;
  g.callMode            = lastCallMode;
  g.transition          = transitionDelay;
  g.nightlightActive    = nightlightActive;
  g.nightlightDelayMins = nightlightDelayMins;
  g.mainSeg             = strip.getMainSegmentId();
  g.flags               = strip.hasCCTBus() ? SYNC_V2_GLOBAL_HAS_CCT : 0;
  g.timebase            = millis() + strip.timebase;
  Toki::Time tm         = toki.getTime();
  g.timeSec             = tm.sec;
  g.timeMs              = tm.ms;
  g.timeSource          = toki.getTimeSource();
  for (size_t i = 0; i < strip.getSegmentsNum(); i++) {
    if (strip.getSegment(i).isActive()) g.segMask |= uint64_t(1) << i;
  }
}

static void fillSegment(SyncV2Segment &r, uint8_t id) {
  const Segment &seg = strip.getSegment(id);
  r.id        = id;
  r.grouping  = seg.grouping;
  r.spacing   = seg.spacing;
  r.opacity   = seg.opacity;
  r.start     = seg.start;
  r.stop      = seg.stop;
  r.startY    = seg.startY;
  r.stopY     = seg.stopY;
  r.offset    = seg.offset;
  r.options   = seg.options;
  r.mode      = seg.mode;
  r.speed     = seg.speed;
  r.intensity = seg.intensity;
  r.palette   = seg.palette;
  for (size_t c = 0; c < 3; c++) r.colors[c] = seg.colors[c];
  r.cct       = seg.cct;
  r.custom1   = seg.custom1;
  r.custom2   = seg.custom2;
  r.custom3   = seg.custom3 | (seg.check1 << 5) | (seg.check2 << 6) | (seg.check3 << 7);
  r.blendMode = seg.blendMode;
}

// split the state into as many parts as needed to fit maxLen and pass each to send()
static void sendStateParts(uint8_t flags, size_t maxLen, bool withNodeInfo, void (*send)(const uint8_t*, size_t)) {
  uint8_t ids[WS2812FX::getMaxSegments()];
  size_t nSegs = 0;
  for (size_t i = 0; i < strip.getSegmentsNum() && nSegs < WS2812FX::getMaxSegments(); i++) {
    if (strip.getSegment(i).isActive()) ids[nSegs++] = i;
  }
  maxLen = std::min(maxLen, SYNC_V2_BUF_SIZE);
  const size_t perPart = (maxLen - SYNC_V2_PART_BASE - (withNodeInfo ? SYNC_V2_NODEINFO_SIZE : 0)) / SYNC_V2_SEG_SIZE;
  const size_t parts = std::max<size_t>(1, (nSegs + perPart - 1) / perPart);

  SyncV2Global g;
  fillGlobal(g);
  uint8_t buf[SYNC_V2_BUF_SIZE];
  for (size_t p = 0; p < parts; p++) {
    SyncV2Header h;
    fillHeader(h, SYNC_V2_MSG_STATE, flags, syncGroups);
    h.part  = p;
    h.parts = parts;
    size_t len = sizeof(h);
    appendTlv(buf, len, SYNC_V2_TLV_GLOBAL, &g, sizeof(g));
    if (withNodeInfo && p == 0) {
      SyncV2NodeInfo ni;
      memcpy(ni.name, serverDescription, sizeof(ni.name));
      ni.build = VERSION;
      ni.board = uint8_t(WLED_BOARD);
      ni.on    = bri > 0;
      appendTlv(buf, len, SYNC_V2_TLV_NODEINFO, &ni, sizeof(ni));
    }
    for (size_t i = p * perPart; i < nSegs && i < (p + 1) * perPart; i++) {
      SyncV2Segment r;
      fillSegment(r, ids[i]);
      appendTlv(buf, len, SYNC_V2_TLV_SEGMENT, &r, sizeof(r));
    }
    h.payloadLen = len - sizeof(h);
    memcpy(buf, &h, sizeof(h));
    send(buf, len);
  }
}

static void sendState(uint8_t flags) {
  DEBUG_PRINTF_P(PSTR("Sync v2: sending state %u/%08x flags %u\n"), (unsigned)myVersion.seq, (unsigned)myVersion.origin, (unsigned)flags);
  if (udpConnected)      sendStateParts(flags, SYNC_V2_MAX_UDP,    true,  sendUdp);
  if (espNowSyncActive()) sendStateParts(flags, SYNC_V2_MAX_ESPNOW, false, sendEspNow);
  nextHeartbeat = millis() + WLED_SYNC_V2_HEARTBEAT + random(SYNC_V2_HEARTBEAT_JITTER);
}

// a state of version (seq, origin) is in effect for the given groups: never apply anything older there
static void markApplied(uint32_t seq, uint32_t origin, uint8_t groups) {
  for (size_t b = 0; b < SYNC_V2_NUM_GROUPS; b++) {
    if (!(groups & (1 << b))) continue;
    if (compareVersion(seq, origin, applied[b].seq, applied[b].origin) > 0) {
      applied[b].seq = seq; applied[b].origin = origin; applied[b].parts = 0xFFFF;
    }
  }
}

static void clearCache() {
  for (size_t p = 0; p < SYNC_V2_MAX_PARTS; p++) free(cache.part[p]);
  cache = SyncV2Cache();
  relayPending = false;
}

static bool cacheComplete() {
  if (!cache.parts) return false;
  for (size_t p = 0; p < cache.parts; p++) if (!cache.part[p]) return false;
  return true;
}

// keep a copy of a received STATE datagram (raw: header + payload) of the latest version
static void cacheStore(const SyncV2Header &h, const uint8_t *raw, size_t rawLen, bool espNow) {
  if (h.parts > SYNC_V2_MAX_PARTS) return;
  if (h.seq != cache.seq || h.origin != cache.origin || !cache.parts) {
    clearCache();
    cache.seq    = h.seq;
    cache.origin = h.origin;
    cache.groups = h.groups;
    cache.parts  = h.parts;
    cache.espNow = espNow;
  }
  if (cache.espNow != espNow || cache.parts != h.parts || cache.part[h.part]) return; // other transport, or already stored
  uint8_t *copy = (uint8_t *)malloc(rawLen);
  if (!copy) return;
  memcpy(copy, raw, rawLen);
  SyncV2Header *ch = reinterpret_cast<SyncV2Header *>(copy); // packed struct, no alignment requirement
  ch->sender = getNodeId();
  ch->flags  = (ch->flags & ~(SYNC_V2_FLAG_HEARTBEAT | SYNC_V2_FLAG_RETRY)) | SYNC_V2_FLAG_RELAY;
  cache.part[h.part] = copy;
  cache.len[h.part]  = rawLen;
}

// a local change was made: create a new version, which we own (and heartbeat)
static void newLocalVersion() {
  clearCache(); // superseded by our own state, we answer STATE_REQ ourselves
  lamport++;
  myVersion.seq    = lamport;
  myVersion.origin = getNodeId();
  hasVersion = true;
  markApplied(myVersion.seq, myVersion.origin, syncGroups);
  lastChange = millis();
  clockCorrected = false;
}

/*
 * applying a received STATE part (receive filters behave like the legacy notifier)
 */
static void applySegment(const SyncV2Segment &r, bool applyEffects, bool applyColor, bool applyPalette) {
  if (r.id >= WS2812FX::getMaxSegments()) return;
  if (receiveSegmentBounds) {
    while (strip.getSegmentsNum() <= r.id) {
      size_t n = strip.getSegmentsNum();
      strip.appendSegment();
      if (strip.getSegmentsNum() == n) break; // no more room
      if (n < r.id) strip.getSegment(n).deactivate(); // filler for an id the sender does not use (ids may have gaps)
    }
  }
  if (r.id >= strip.getSegmentsNum()) return;
  Segment &seg = strip.getSegment(r.id);
  // without bounds sync only the active and selected local segments follow
  if (!receiveSegmentBounds && !(seg.isActive() && seg.isSelected())) return;

  if (!receiveSegmentOptions) {
    seg.setGeometry(r.start, r.stop, seg.grouping, seg.spacing, r.offset, r.startY, r.stopY, seg.map1D2D);
    return;
  }
  seg.options = (seg.options & SYNC_V2_KEEP_OPTIONS) | (r.options & ~SYNC_V2_KEEP_OPTIONS);
  seg.setOpacity(r.opacity);
  seg.blendMode = r.blendMode;
  if (applyEffects) {
    seg.setMode(r.mode);
    seg.speed     = r.speed;
    seg.intensity = r.intensity;
    seg.custom1   = r.custom1;
    seg.custom2   = r.custom2;
    seg.custom3   = r.custom3 & 0x1F;
    seg.check1    = (r.custom3 >> 5) & 0x1;
    seg.check2    = (r.custom3 >> 6) & 0x1;
    seg.check3    = (r.custom3 >> 7) & 0x1;
  }
  if (applyPalette) seg.setPalette(r.palette);
  if (applyColor) {
    for (size_t c = 0; c < 3; c++) seg.setColor(c, r.colors[c]);
    seg.setCCT(r.cct);
  }
  if (receiveSegmentBounds) seg.setGeometry(r.start, r.stop, r.grouping, r.spacing, r.offset, r.startY, r.stopY, seg.map1D2D);
  else                      seg.setGeometry(seg.start, seg.stop, r.grouping, r.spacing, seg.offset, seg.startY, seg.stopY, seg.map1D2D);
}

static void applyState(const SyncV2Global &g, const uint8_t *tlvs, size_t tlvLen) {
  const bool someSel      = receiveNotificationBrightness || receiveNotificationColor || receiveNotificationEffects || receiveNotificationPalette;
  const bool applyEffects = receiveNotificationEffects || !someSel;
  const bool applyColor   = receiveNotificationColor   || !someSel;
  const bool applyPalette = receiveNotificationPalette || !someSel;

  jsonTransitionOnce = true;
  strip.setTransition(g.transition);
  if (applyEffects && currentPlaylist >= 0) unloadPlaylist();

  const bool syncSegments = receiveSegmentOptions || receiveSegmentBounds;
  if (syncSegments && receiveSegmentBounds) {
    // segment ids are real ids: remove local segments the sender does not have
    for (size_t i = 0; i < strip.getSegmentsNum(); i++) {
      Segment &seg = strip.getSegment(i);
      if (seg.isActive() && !(g.segMask & (uint64_t(1) << i))) seg.deactivate();
    }
  }
  for (size_t ofs = 0; ofs + sizeof(SyncV2Tlv) <= tlvLen; ) {
    SyncV2Tlv t;
    memcpy(&t, tlvs + ofs, sizeof(t));
    ofs += sizeof(t);
    if (t.type == SYNC_V2_TLV_SEGMENT && t.len >= sizeof(SyncV2Segment)) {
      SyncV2Segment r;
      memcpy(&r, tlvs + ofs, sizeof(r)); // only the known prefix, newer senders may append fields
      if (syncSegments) applySegment(r, applyEffects, applyColor, applyPalette);
      else if (r.id == g.mainSeg) {
        // simple sync: sender's main segment drives our main segment colors and all selected segments' effect
        if (applyColor) {
          for (size_t c = 0; c < 3; c++) strip.getMainSegment().setColor(c, r.colors[c]);
          if (g.flags & SYNC_V2_GLOBAL_HAS_CCT) strip.setCCT(r.cct);
        }
        for (size_t i = 0; i < strip.getSegmentsNum(); i++) {
          Segment &seg = strip.getSegment(i);
          if (!seg.isActive() || !seg.isSelected()) continue;
          if (applyEffects) {
            seg.setMode(r.mode);
            seg.speed     = r.speed;
            seg.intensity = r.intensity;
          }
          if (applyPalette) seg.setPalette(r.palette);
        }
      }
    }
    ofs += t.len; // validated by caller
  }
  stateChanged = true;

  bool timebaseUpdated = false;
  if (applyEffects) {
    strip.timebase = g.timebase + SYNC_V2_NETWORK_DELAY - millis();
    timebaseUpdated = true;
  }

  // adjust system time, but only if sender is more accurate than self (same as legacy notifier)
  Toki::Time tm;
  tm.sec = g.timeSec;
  tm.ms  = g.timeMs;
  if (g.timeSource > toki.getTimeSource()) {
    toki.adjust(tm, SYNC_V2_NETWORK_DELAY);
    uint8_t ts = TOKI_TS_UDP;
    if (g.timeSource > 99) ts = TOKI_TS_UDP_NTP;
    else if (g.timeSource >= TOKI_TS_SEC) ts = TOKI_TS_UDP_SEC;
    toki.setTime(tm, ts);
  } else if (timebaseUpdated && toki.getTimeSource() > 99) {
    Toki::Time myTime = toki.getTime();
    uint32_t diff = toki.msDifference(tm, myTime);
    strip.timebase -= SYNC_V2_NETWORK_DELAY;
    if (toki.isLater(tm, myTime)) strip.timebase += diff;
    else                          strip.timebase -= diff;
  }

  nightlightActive = g.nightlightActive;
  if (nightlightActive) nightlightDelayMins = g.nightlightDelayMins;
  if (receiveNotificationBrightness || !someSel) bri = g.bri;
  stateUpdated(CALL_MODE_NOTIFICATION);
}

static void updateNodeList(const SyncV2NodeInfo &ni, const IPAddress &src) {
  if (!nodeListEnabled || src == IPAddress(0,0,0,0)) return;
  uint8_t unit = src[3]; // same key as the legacy node info broadcast
  NodesMap::iterator it = Nodes.find(unit);
  if (it == Nodes.end()) {
    if (Nodes.size() >= WLED_MAX_NODES) return;
    it = Nodes.emplace(unit, NodeStruct()).first;
  }
  it->second.ip  = src;  // from the datagram, not the payload
  it->second.age = 0;
  char name[sizeof(ni.name) + 1];
  memcpy(name, ni.name, sizeof(ni.name));
  name[sizeof(ni.name)] = 0;
  it->second.nodeName = name;
  it->second.nodeName.trim();
  it->second.nodeType = ni.board | (ni.on ? 0x80 : 0);
  it->second.build    = ni.build;
}

// raw: complete datagram (header + payload), src: sender IP or 0.0.0.0 for ESP-NOW
static void handleState(const SyncV2Header &h, const uint8_t *raw, size_t rawLen, const IPAddress &src) {
  const uint8_t *tlvs = raw + sizeof(SyncV2Header);
  const size_t tlvLen = rawLen - sizeof(SyncV2Header);
  // validate TLVs and find the global section
  SyncV2Global g {};
  bool hasGlobal = false;
  for (size_t ofs = 0; ofs + sizeof(SyncV2Tlv) <= tlvLen; ) {
    SyncV2Tlv t;
    memcpy(&t, tlvs + ofs, sizeof(t));
    ofs += sizeof(t);
    if (ofs + t.len > tlvLen) {
      DEBUG_PRINTLN(F("Sync v2: truncated TLV."));
      return;
    }
    if (t.type == SYNC_V2_TLV_GLOBAL && t.len >= sizeof(g)) {
      memcpy(&g, tlvs + ofs, sizeof(g));
      hasGlobal = true;
    } else if (t.type == SYNC_V2_TLV_NODEINFO && t.len >= sizeof(SyncV2NodeInfo) && !(h.flags & SYNC_V2_FLAG_RELAY)) {
      // (a relayed datagram carries the origin's node info, but comes from the relaying node's IP)
      SyncV2NodeInfo ni;
      memcpy(&ni, tlvs + ofs, sizeof(ni));
      updateNodeList(ni, src);
    }
    ofs += t.len;
  }
  if (!hasGlobal) return;

  const uint8_t groups = h.groups & receiveGroups;
  if (!groups || realtimeMode) return;

  // another node already answered a STATE_REQ with the state we were about to relay
  if (relayPending && h.seq == cache.seq && h.origin == cache.origin) relayPending = false;

  // compare with what we applied for each of the message's groups we receive
  bool newer = false, missingPart = false, stale = true;
  for (size_t b = 0; b < SYNC_V2_NUM_GROUPS; b++) {
    if (!(groups & (1 << b))) continue;
    int cmp = compareVersion(h.seq, h.origin, applied[b].seq, applied[b].origin);
    if (cmp > 0) newer = true;
    if (cmp == 0 && !(applied[b].parts & partBit(h.part))) missingPart = true;
    if (cmp >= 0) stale = false;
  }
  if (stale) {
    // the sender is behind (e.g. it rebooted): tell it our clock so it can re-send its change with a newer version
    if (!(h.flags & (SYNC_V2_FLAG_HEARTBEAT | SYNC_V2_FLAG_RELAY)) && millis() - lastClockSent > SYNC_V2_CLOCK_MIN_GAP) {
      lastClockSent = millis();
      sendControl(SYNC_V2_MSG_CLOCK, groups);
    }
    return;
  }
  if (!newer && !missingPart) return; // already applied (duplicate, retry or heartbeat)

  DEBUG_PRINTF_P(PSTR("Sync v2: applying %u/%08x part %u/%u\n"), (unsigned)h.seq, (unsigned)h.origin, (unsigned)h.part, (unsigned)h.parts);
  for (size_t b = 0; b < SYNC_V2_NUM_GROUPS; b++) {
    if (!(groups & (1 << b))) continue;
    if (compareVersion(h.seq, h.origin, applied[b].seq, applied[b].origin) > 0) {
      applied[b].seq = h.seq; applied[b].origin = h.origin; applied[b].parts = 0;
    }
    applied[b].parts |= partBit(h.part);
  }
  applyState(g, tlvs, tlvLen);
  cacheStore(h, raw, rawLen, src == IPAddress(0,0,0,0));

  // only the origin advertises a version: our copy may differ from the original (receive filters, strip length, ...),
  // and an equal version is never re-applied, so re-advertising it could leave late joiners with a wrong state
  hasVersion = false;
  if (h.groups & syncGroups) {
    markApplied(h.seq, h.origin, h.groups & syncGroups); // a newer state supersedes our own change ...
    notificationCount = udpNumRetries;                    // ... so drop its pending retries
  }
}

/*
 * public interface
 */

// send our state after a local change (followUp: retry of the last change)
void syncV2Send(byte callMode, bool followUp) {
  if (followUp) {
    if (!hasVersion) return; // state changed since without being sent, retrying would advertise it under the old version
  } else {
    lastCallMode = callMode;
    newLocalVersion();
  }
  sendState(followUp ? SYNC_V2_FLAG_RETRY : 0);
}

// local state changed without being sent: it must not be advertised in heartbeats
void syncV2Diverged() {
  hasVersion = false;
}

// handle a received v2 datagram (src: sender IP, or 0.0.0.0 for ESP-NOW)
void syncV2Handle(const uint8_t *buf, size_t len, const IPAddress &src) {
  SyncV2Header h;
  if (len < sizeof(h)) return;
  memcpy(&h, buf, sizeof(h));
  if (h.magic[0] != SYNC_V2_MAGIC0 || h.magic[1] != SYNC_V2_MAGIC1 || h.magic[2] != SYNC_V2_MAGIC2 || h.magic[3] != SYNC_V2_MAGIC3) return;
  if (h.version < SYNC_V2_VERSION) return;              // newer versions keep the header layout
  if (h.payloadLen > len - sizeof(h)) return;
  if (h.sender == getNodeId()) return;                 // our own broadcast
  if (h.parts == 0 || h.part >= h.parts) return;

  if (int32_t(h.seq - lamport) > 0) lamport = h.seq;   // Lamport clock: never fall behind any seq seen

  switch (h.msgType) {
    case SYNC_V2_MSG_STATE:
      handleState(h, buf, sizeof(h) + h.payloadLen, src);
      break;
    case SYNC_V2_MSG_STATE_REQ: {
      // a node joined: send the state soon (random delay so not all nodes answer at once)
      unsigned long soon = millis() + 20 + random(300);
      if (hasVersion && sendNotificationsRT && (h.groups & syncGroups)) {
        // we are the origin of our state
        if (int32_t(nextHeartbeat - soon) > 0) nextHeartbeat = soon;
      } else if ((cache.groups & h.groups) && cacheComplete() && !relayPending) {
        // relay the origin's datagrams, unless another node does so first (see handleState())
        relayPending = true;
        relayAt = soon;
      }
      break;
    }
    case SYNC_V2_MSG_CLOCK:
      // our recent change was older than what others have: re-send it with a newer version (once)
      if (hasVersion && myVersion.origin == getNodeId() && !clockCorrected && millis() - lastChange < SYNC_V2_CLOCK_WINDOW
          && (h.groups & syncGroups)) {
        newLocalVersion();
        clockCorrected = true;
        sendState(0);
      }
      break;
    default:
      break;
  }
}

// periodic tasks, called from handleNotifications()
void syncV2Loop() {
  static bool wasConnected = false;
  static unsigned long joinAt = 0;
  static bool joinPending = false;
  const unsigned long now = millis();

  const bool connected = udpConnected || espNowSyncActive();
  if (connected && !wasConnected) {
    joinAt = now + SYNC_V2_JOIN_DELAY + random(SYNC_V2_JOIN_DELAY);
    joinPending = true;
  }
  wasConnected = connected;
  if (!connected) return;

  if (joinPending && int32_t(now - joinAt) >= 0) {
    joinPending = false;
    if (receiveGroups) sendControl(SYNC_V2_MSG_STATE_REQ, receiveGroups);
  }

  if (hasVersion && sendNotificationsRT && syncGroups && int32_t(now - nextHeartbeat) >= 0) {
    sendState(SYNC_V2_FLAG_HEARTBEAT);
  }

  if (relayPending && int32_t(now - relayAt) >= 0) {
    relayPending = false;
    if (cacheComplete()) {
      DEBUG_PRINTF_P(PSTR("Sync v2: relaying %u/%08x (%u parts)\n"), (unsigned)cache.seq, (unsigned)cache.origin, (unsigned)cache.parts);
      for (size_t p = 0; p < cache.parts; p++) {
        if (cache.espNow) sendEspNow(cache.part[p], cache.len[p]);
        else              sendUdp(cache.part[p], cache.len[p]);
      }
    }
  }
}
